const upd = $('Message Telegram').first().json;
const msg = upd.message || {};
if (!msg.chat || msg.chat.type !== 'private') return [];
const chatId = String(msg.chat.id);
const users = $input.all().map(i => i.json);
const u = users.find(x => x.actif && String(x.telegram_id) === chatId);
if (!u) return [];
const q = String(msg.text || '').trim();
if (!q) return [];
return [{ json: { chat_id: chatId, interfast_id: Number(u.interfast_id), role: String(u.role || ''), nom: String(u.nom || ''), question: q.slice(0, 500) } }];

const ctx = $('Controle acces').first().json;
const now = DateTime.now().setZone('Europe/Paris');
let intent = 'autre', date = now.toISODate(), jours = 14, jourPrecis = false;
try {
  const t = ($input.first().json.content || []).map(c => c.text || '').join('').replace(/```json|```/g, '').trim();
  const p = JSON.parse(t);
  if (['prochain_rdv', 'telephone', 'adresse', 'autre'].includes(p.intent)) intent = p.intent;
  if (p.date) {
    const d = DateTime.fromISO(String(p.date), { zone: 'Europe/Paris' });
    if (d.isValid) {
      const ecart = d.startOf('day').diff(now.startOf('day'), 'days').days;
      if (ecart >= -7 && ecart <= 60) { date = d.toISODate(); jours = 1; jourPrecis = true; }
    }
  }
} catch (e) {}
return [{ json: { ...ctx, intent, date, jours, jourPrecis, estAujourdhui: date === now.toISODate() } }];

const sel = $('Trouver prochain RDV').first().json;
const now = DateTime.now().setZone('Europe/Paris');
function libJour(iso) {
  const d = DateTime.fromISO(iso, { zone: 'Europe/Paris' }).startOf('day');
  const ecart = d.diff(now.startOf('day'), 'days').days;
  if (ecart === 0) return "Aujourd'hui";
  if (ecart === 1) return 'Demain';
  return d.setLocale('fr').toFormat('cccc d LLLL');
}
const h = String(sel.heure || '?').replace(':', 'h').replace(/^0/, '');
const quand = (sel.dateRdv ? libJour(sel.dateRdv) + ' ' : '') + (sel.code === 1 ? h + ' (approx.)' : sel.code === 2 ? h + ' (demi-journee)' : sel.code === 3 ? h + ' (journee entiere)' : h);
let text = '';
if (sel.intent === 'autre') {
  text = "Pour l'instant je ne reponds qu'a : prochain RDV, telephone du client, adresse.";
} else if (!sel.trouve) {
  if (!sel.jourPrecis) text = 'Aucun RDV prevu dans les 14 prochains jours.';
  else text = sel.estAujourdhui ? "Plus rien au planning aujourd'hui." : 'Rien au planning ' + libJour(sel.date).toLowerCase() + '.';
} else if (sel.intent === 'adresse') {
  text = sel.adresse ? (quand + ' - ' + (sel.clientNom || sel.titre) + '\n' + sel.adresse) : 'Pas d adresse sur ce RDV.';
} else if (sel.intent === 'telephone') {
  let tel = '', nomContact = '';
  try {
    const r = $input.first().json;
    const c = (r && r.ok && r.data) || null;
    if (c) {
      const g = c.clientParticular || c.clientProfessional || c.clientOwnersAssociation || {};
      const contacts = g.contacts || [];
      const ct = contacts.find(x => (x.roles || []).includes('primary')) || contacts.find(x => x.phoneNumber) || g.contact;
      if (ct && ct.phoneNumber) { tel = String(ct.phoneNumber); nomContact = [ct.firstName, ct.lastName].filter(Boolean).join(' '); }
    }
  } catch (e) {}
  if (!sel.clientId) text = 'Pas de client relie a ce RDV (' + quand + ' - ' + sel.titre + ').';
  else if (!tel) text = 'Pas de numero dans la fiche de ' + (sel.clientNom || 'ce client') + '.';
  else text = quand + ' - ' + (sel.clientNom || '') + '\n' + (nomContact ? nomContact + ' : ' : '') + tel;
} else {
  const objet = sel.titre && sel.titre !== sel.type ? sel.titre : sel.type;
  text = 'Prochain RDV : ' + quand + ' - ' + [sel.clientNom, sel.adresse].filter(Boolean).join(', ') + (objet ? '\n' + objet : '');
}
return [{ json: { chat_id: sel.chat_id, text } }];

const ctx = $('Extraire intention').first().json;
function items(n) {
  try { const r = $(n).first().json; return (r && r.ok && r.data && r.data.items) || []; } catch (e) { return []; }
}
const tous = items('Lire interventions du jour').concat(items('Lire RDV du jour'));
const now = DateTime.now().setZone('Europe/Paris');
const cands = tous
  .filter(ev => !ev.finished && ev.lifecycleState !== 'cancelled' && ev.codeHoraire !== 4 && ev.start)
  .filter(ev => !ctx.estAujourdhui || DateTime.fromISO(ev.start, { zone: 'utc' }) > now)
  .sort((a, b) => String(a.start).localeCompare(String(b.start)));
const ev = cands[0];
if (!ev) return [{ json: { ...ctx, trouve: false, clientId: '' } }];
return [{ json: {
  ...ctx, trouve: true,
  dateRdv: ev.dateParis || ctx.date,
  clientId: (ev.client && ev.client.id) ? String(ev.client.id) : '',
  clientNom: (ev.client && ev.client.name) || '',
  heure: ev.heureParis || '?', libelle: ev.horaireLibelle || '', code: ev.codeHoraire,
  titre: ev.title || '', type: ev.type || '', adresse: ev.address || ''
} }];
